<?php
require_once __DIR__.'/config/database.php';require_once __DIR__.'/includes/auth.php';require_admin();
if($_SERVER['REQUEST_METHOD']==='POST'){try{$action=$_POST['action']??'';if($action==='save'){$id=(int)($_POST['id']??0);$v=[trim($_POST['name']??''),trim($_POST['phone']??''),trim($_POST['email']??''),trim($_POST['address']??'')];if($v[0]==='')throw new Exception();if($id){$v[]=$id;$s=$pdo->prepare('UPDATE suppliers SET name=?,phone=?,email=?,address=? WHERE id=?');}else{$s=$pdo->prepare('INSERT INTO suppliers(name,phone,email,address) VALUES(?,?,?,?)');}$s->execute($v);$_SESSION['flash']='Supplier berhasil disimpan.';}elseif($action==='delete'){$s=$pdo->prepare('DELETE FROM suppliers WHERE id=?');$s->execute([(int)$_POST['id']]);$_SESSION['flash']='Supplier dihapus.';}}catch(Throwable $e){$_SESSION['flash']='Supplier gagal disimpan/dihapus. Supplier yang terhubung ke produk tidak dapat dihapus.';}header('Location: suppliers.php');exit;}
$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM suppliers WHERE id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}
$rows=$pdo->query('SELECT s.*,COUNT(ps.product_id) product_count FROM suppliers s LEFT JOIN product_suppliers ps ON ps.supplier_id=s.id GROUP BY s.id ORDER BY s.name')->fetchAll();$pageTitle='Supplier';include __DIR__.'/includes/header.php';?>
<div class="grid-2"><section class="panel"><div class="panel-head"><h2><?= $edit?'Edit supplier':'Tambah supplier' ?></h2></div><form method="post"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?= (int)($edit['id']??0) ?>"><div class="form-grid"><div class="field full"><label>Nama supplier *</label><input name="name" required value="<?= h($edit['name']??'') ?>"></div><div class="field"><label>Telepon</label><input name="phone" value="<?= h($edit['phone']??'') ?>"></div><div class="field"><label>Email</label><input type="email" name="email" value="<?= h($edit['email']??'') ?>"></div><div class="field full"><label>Alamat</label><textarea name="address" rows="2"><?= h($edit['address']??'') ?></textarea></div></div><div class="form-actions"><button class="btn">Simpan supplier</button><?php if($edit): ?><a class="btn secondary" href="suppliers.php">Batal</a><?php endif; ?></div></form></section><section class="panel"><div class="panel-head"><h2>Relasi Supplier</h2></div><p class="muted">Tabel relasi many-to-many produk-supplier tersedia di database melalui <code>product_suppliers</code>. Data harga supplier dapat disimpan per pasangan produk dan supplier.</p><div class="stat-number"><?= count($rows) ?></div><div class="muted">Supplier terdaftar</div></section></div>
<section class="panel"><div class="panel-head"><h2>Daftar Supplier</h2></div><div class="table-wrap"><table><thead><tr><th>NAMA</th><th>KONTAK</th><th>EMAIL</th><th>PRODUK TERKAIT</th><th>AKSI</th></tr></thead><tbody><?php foreach($rows as $s): ?><tr><td class="product-name"><?= h($s['name']) ?><div class="muted"><?= h($s['address']??'') ?></div></td><td><?= h($s['phone']??'—') ?></td><td><?= h($s['email']??'—') ?></td><td><?= (int)$s['product_count'] ?></td><td><a class="btn secondary small" href="?edit=<?= (int)$s['id'] ?>">Edit</a> <form method="post" style="display:inline" onsubmit="return confirm('Hapus supplier?')"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= (int)$s['id'] ?>"><button class="btn danger small">Hapus</button></form></td></tr><?php endforeach; ?></tbody></table></div></section>
<?php include __DIR__.'/includes/footer.php';?>